<?php declare(strict_types=1); use Kulturhus\Verein\MemberChangeRequests;$change=$changeUi['selected'];$changeId=$change['id'];$changeCreated=localDateTime($change['created_at']);?>
<a class="btn btn-outline theme-secondary" href="<?=e($changeUrl())?>"><?=e($changeText('Alle Änderungsanträge'))?></a>
<section class="card" data-member-change-reader><header><h2><?=e($change['current']['name'])?></h2><span class="status"><?=e($changeText(MemberChangeRequests::STATES[$change['state']]))?></span><p><?=e($changeText('Eingereicht am {date} um {time}.',['date'=>dateDe(substr($changeCreated,0,10)),'time'=>timeDe($change['created_at'])]))?></p></header>
<div class="member-change-comparison"><?php foreach(MemberChangeRequests::FIELDS as$field=>$label):if($change['data']['before'][$field]===$change['data']['after'][$field])continue;?><article><h3><?=e($changeText($label))?></h3><?php foreach(['before'=>$change['state']==='accepted'?'Bisher':'Bei Einreichung','after'=>$change['state']==='accepted'?'Übernommen':'Vorgeschlagen']as$side=>$caption):$value=$change['data'][$side][$field];?><div><strong><?=e($changeText($caption))?></strong><p><?=nl2br(e($value!==''?$value:$changeText($side==='before'?'Nicht hinterlegt':'Angabe entfernen')))?></p></div><?php endforeach?><?php if($change['state']==='pending'&&$change['conflict']):$value=$change['current'][$field];?><div><strong><?=e($changeText('Inzwischen im Profil'))?></strong><p><?=nl2br(e($value!==''?$value:$changeText('Nicht hinterlegt')))?></p></div><?php endif?></article><?php endforeach?></div>
<?php if($change['data']['decision_note']!==''):?><h3><?=e($changeText('Rückmeldung des Vorstands'))?></h3><p><?=nl2br(e($change['data']['decision_note']))?></p><?php endif?>
<?php if($changeUi['lookup']):?><a class="btn btn-outline theme-secondary" href="<?=e($changeUrl(['change'=>$changeId]))?>"><?=e($changeText('Gespeicherten Antrag öffnen'))?></a>
<?php elseif($change['state']==='pending'):?>
<?php if($reviewChanges):?>
<?php if($change['conflict']||!$change['current_member']):?><p class="notice"><?=e($changeText($change['conflict']?'Das Profil wurde nach dem Einreichen geändert. Bitte den Antrag mit einer verständlichen Begründung ablehnen; das Mitglied kann die aktuellen Angaben vergleichen und neu einreichen.':'Die Mitgliedschaft ist nicht mehr aktuell. Die vorgeschlagenen Angaben können hier nicht übernommen werden.'))?></p><?php endif?>
<form method="post" action="<?=e($changeUrl(['change'=>$changeId]))?>" data-member-change-review><?=csrf().hidden('action','member-change-review').hidden('change',$changeId).hidden('change_version',$change['version'])?><label><?=e($changeText('Rückmeldung an das Mitglied'))?><textarea class="form-control" name="decision_note" maxlength="2000" rows="4" <?=$change['conflict']||!$change['current_member']?'required':''?>></textarea></label><p><?=e($changeText('Die Rückmeldung steht beim Änderungsantrag im Mitgliederkonto. Bei einer Ablehnung bitte den Grund nennen.'))?></p><label class="check"><input class="check" type="checkbox" name="confirm_change" value="1" required><span><?=e($changeText('Ich habe den ursprünglichen Antrag mit den aktuellen Profildaten verglichen und bestätige die gewählte Entscheidung.'))?></span></label><div class="actions"><?php if(!$change['conflict']&&$change['current_member']):?><button class="btn btn-solid theme-primary" name="decision" value="accepted"><?=e($changeText('Geprüfte Angaben übernehmen'))?></button><?php endif?><button class="btn btn-outline theme-secondary" name="decision" value="rejected"><?=e($changeText('Nicht übernehmen'))?></button></div></form>
<?php else:?><p><?=e($changeText('Der Vorstand prüft deinen Antrag. Deine bisherigen Angaben bleiben bis zur Übernahme gültig.'))?></p><form method="post" action="<?=e($changeUrl(['change'=>$changeId]))?>" data-member-change-withdraw><?=csrf().hidden('action','member-change-withdraw').hidden('change',$changeId).hidden('change_version',$change['version'])?><label class="check"><input class="check" type="checkbox" name="confirm_change" value="1" required><span><?=e($changeText('Ich ziehe genau diesen noch offenen Änderungsantrag zurück.'))?></span></label><button class="btn btn-outline theme-secondary"><?=e($changeText('Antrag zurückziehen'))?></button></form><?php endif?>
<?php elseif(!$reviewChanges):?><a class="btn btn-outline theme-secondary" href="<?=e($changeUrl())?>"><?=e($changeText('Neue Änderung vorschlagen'))?></a><?php endif?>
<p class="member-change-login-note"><?=e($changeText('Die Kontakt-E-Mail gehört zu deinem Mitgliederprofil. Benutzername, Passwort und die Adresse zum Zurücksetzen des Passworts werden damit nicht geändert. Gemeinsame Familien-E-Mail-Adressen sind weiterhin möglich.'))?></p></section>
